from helpers import *
LU="Lucent's General Knowledge"
NC8="NCERT Class 6-8 Social Science (History): Our Pasts I-III"; NC11="NCERT Class 11, An Introduction to Indian Art / Themes in World History"
W=week(HRS,{"quant":["Time & Work"],"reasoning":["Ranking","Calendar","Clock"],"english":["Voice","Narration"],"ga":["Ancient & Medieval History"]},
unit("Quant: Time and work, pipes and cisterns",[
 part("Part 1: Time and work",
  [rd(RSA,"Chapter 'Time and Work': theory and solved examples"),rd(KM,"Chapter 'Time and Work': first 10 solved questions")],
  ["If A does a job in x days, A's one-day work = 1/x. A and B together: 1/x + 1/y = (x + y)/xy, so time = xy/(x + y).",
   "LCM method: take total work = LCM of the days. Efficiency = work ÷ days. Time together = total work ÷ sum of efficiencies. (A in 12 days, B in 24: work = 24, A = 2/day, B = 1/day, together 3/day = 8 days.)",
   "If A is n times as efficient as B, A takes 1/n of B's time.",
   "Man-days rule: M1 × D1 × H1 / W1 = M2 × D2 × H2 / W2.",
   "If A and B together take t days and A alone takes a days: B alone = at/(a − t)."],
  [ex("A can do a job in 12 days and B in 24 days. In how many days together?","8","12 × 24/(12 + 24) = 8."),
   ex("A and B together finish in 12 days. A alone takes 20 days. B alone?","30 days","1/12 − 1/20 = 1/30."),
   ex("10 men build a wall in 15 days. How long will 6 men take?","25 days","10 × 15 = 150 man-days, 150/6 = 25."),
   ex("A is twice as efficient as B. Together they take 18 days. A alone?","27 days","B alone = 54, A alone = 27.")],
  [sv("Book practice, 60 minutes max","RSA 'Time and Work': first 40 questions."),sv("Previous-year questions","KM 'Time and Work': 25 questions, 45 seconds each."),sv("App drill",None,dr("quant","Time & Work",20,15))]),
 part("Part 2: Pipes and cisterns",
  [rd(RSA,"Chapter 'Pipes and Cisterns'"),rd(KM,"Chapter 'Pipes and Cisterns': first 10 solved questions")],
  ["Inlet pipes do positive work, outlet pipes and leaks do negative work. Net rate = sum of all rates.",
   "A fills in x hours, B empties in y hours (y > x): time to fill = xy/(y − x).",
   "Leak: if a tank fills in a hours normally and b hours with a leak, the leak empties a full tank in ab/(b − a) hours.",
   "Use the LCM method with a capacity in litres: work = capacity, efficiency = litres per hour."],
  [ex("Pipe A fills a tank in 6 h, pipe B empties it in 9 h. Both open: time to fill?","18 hours","6 × 9/(9 − 6) = 18."),
   ex("A fills in 20 min, B in 30 min. Together?","12 minutes","20 × 30/50 = 12."),
   ex("A tank fills in 6 h. A leak makes it 7 h. How long does the leak take to empty it?","42 hours","6 × 7/(7 − 6) = 42."),
   ex("A and B fill in 10 h and 15 h; C empties in 30 h. All open: time to fill?","7.5 hours","1/10 + 1/15 − 1/30 = 4/30.")],
  [sv("Book practice, 60 minutes max","RSA 'Pipes and Cisterns': first 30 questions."),sv("Previous-year questions","KM 'Pipes and Cisterns': 15 questions."),sv("App drill",None,dr("quant","Time & Work",20,15,"85%"))]),
 part("Part 3: Leaving, alternate days and wages",
  [rd(RSA,"Time and Work: harder exercises (leaving midway, alternate days, wages)"),rd(KM,"Chapter 'Time and Work': questions 26 to 50")],
  ["Work done so far + work left = 1. Write the fraction done before computing what remains.",
   "Alternate days (A first, then B): find the work done in two days, then multiply to cover the cycles.",
   "Wages are shared in proportion to work done (efficiency × days), not days alone.",
   "If x and y are the times for two persons, their efficiencies are in the ratio y : x."],
  [ex("A takes 20 days, B takes 30. They work together 6 days, then A leaves. B alone finishes in?","15 days","6 × (1/12) = 1/2 done; B needs 1/2 ÷ (1/30) = 15."),
   ex("A and B do a job in 8 and 12 days. Total wage ₹1,000. Find A's share.","₹600","Efficiencies 3 : 2, so A gets 3/5 of 1,000 = 600."),
   ex("A in 10 days, B in 15 days, working on alternate days starting with A. Total time?","12 days","In 2 days they do 1/10 + 1/15 = 1/6; 6 cycles = 12 days.")],
  [sv("Book practice, 60 minutes max","RSA 'Time and Work': questions 41 to 70."),sv("Previous-year questions","KM: 20 more questions."),sv("App drill",None,dr("quant","Time & Work",20,15,"85%"))])]),
unit("Reasoning: Ranking, calendar, clock",[
 part("Part 1: Ranking and order",
  [rd(RV,"Chapter 'Ranking Test' / 'Order and Ranking'"),rd(KR,"Chapter 'Ranking': first 15 questions")],
  ["Total = rank from top + rank from bottom − 1. Rank from bottom = total − rank from top + 1.",
   "Persons between two positions = difference of ranks − 1.",
   "If a person moves up or down, recompute both ranks. Draw a line and mark positions.",
   "In a row: total = (position from left) + (position from right) − 1."],
  [ex("Ravi is 7th from the top in a class of 40. What is his rank from the bottom?","34","40 − 7 + 1 = 34."),
   ex("Anil is 12th from the left and 15th from the right in a row. How many persons?","26","12 + 15 − 1 = 26."),
   ex("A is 5th from the top and B is 18th from the top. How many are between them?","12","18 − 5 − 1 = 12."),
   ex("In a class of 45, Meena is 18th from the top and Seema is 10 places below her. Seema's rank from the bottom?","18","Seema is 28th from top, 45 − 28 + 1 = 18.")],
  [sv("Book practice, 40 minutes","RV 'Ranking Test': 30 questions."),sv("Previous-year questions","KR: 20 questions."),sv("App drill",None,dr("reasoning","Ranking",15,10))]),
 part("Part 2: Calendar",
  [rd(RV,"Chapter 'Calendar'"),rd(KR,"Chapter 'Calendar': first 15 questions")],
  ["Odd days: ordinary year = 1, leap year = 2. 100 years = 5, 200 = 3, 300 = 1, 400 = 0.",
   "Leap year: divisible by 4; century years only if divisible by 400 (2000 is, 2100 is not).",
   "Code: Sun 0, Mon 1, Tue 2, Wed 3, Thu 4, Fri 5, Sat 6.",
   "Month odd days (ordinary year): Jan 3, Feb 0, Mar 3, Apr 2, May 3, Jun 2, Jul 3, Aug 3, Sep 2, Oct 3, Nov 2, Dec 3.",
   "Same calendar repeats after 6, 11, 5 or 28 years depending on the leap-year positions.",
   "Reference dates: 15 Aug 1947 was a Friday. 26 Jan 1950 was a Thursday."],
  [ex("Today is Monday. What day is it after 45 days?","Thursday","45 mod 7 = 3, Monday + 3 = Thursday."),
   ex("15 Aug 1947 was a Friday. What day was 15 Aug 1948?","Sunday","1948 is a leap year, so 366 days = 2 odd days: Friday + 2 = Sunday."),
   ex("Is 2100 a leap year?","No","A century year must be divisible by 400."),
   ex("28 Nov 2026 is a Saturday. What day is 1 Jan 2027?","Friday","34 days later: 34 mod 7 = 6, Saturday + 6 = Friday.")],
  [sv("Book practice, 40 minutes","RV 'Calendar': 25 questions."),sv("Previous-year questions","KR: 15 questions."),sv("App drill",None,dr("reasoning","Calendar",15,10))]),
 part("Part 3: Clock",
  [rd(RV,"Chapter 'Clocks'"),rd(KR,"Chapter 'Clock': first 15 questions")],
  ["Minute hand moves 6° per minute; hour hand 0.5° per minute. Angle = |30h − 5.5m|; if more than 180°, subtract from 360°.",
   "Hands coincide 11 times in 12 hours (22 times a day). They are at right angles 22 times in 12 hours and opposite 11 times in 12 hours.",
   "Hands coincide at 12:00, then every 65 5/11 minutes.",
   "To find the time when the hands coincide after h o'clock: minutes = 60h/11."],
  [ex("Angle between the hands at 3:30?","75°","|90 − 165| = 75."),ex("Angle at 4:20?","10°","|120 − 110| = 10."),ex("When do the hands coincide after 4 o'clock?","4:21 9/11","60 × 4/11 = 21 9/11 minutes.")],
  [sv("Book practice, 40 minutes","RV 'Clocks': 25 questions."),sv("Previous-year questions","KR: 15 questions."),sv("App drill",None,dr("reasoning","Clock",15,10))])]),
unit("English: Active-passive and direct-indirect speech",[
 part("Part 1: Active and passive voice (basic tenses)",
  [rd(WM,"Chapter 'Voice' (Active and Passive)"),rd(SB,"Chapter 'Active and Passive Voice'")],
  ["Active: subject + verb + object. Passive: object + be-verb + V3 + by + subject.",
   "Simple present: is/am/are + V3. Simple past: was/were + V3. Simple future: will be + V3.",
   "Present continuous: is/am/are being + V3. Past continuous: was/were being + V3.",
   "Present perfect: has/have been + V3. Past perfect: had been + V3.",
   "Pronouns change: I→me, we→us, he→him, she→her, they→them (and back)."],
  [ex("Passive: 'She wrote a letter.'","A letter was written by her."),ex("Passive: 'They have completed the work.'","The work has been completed by them."),ex("Passive: 'The boy is flying a kite.'","A kite is being flown by the boy.")],
  [sv("Book practice, 45 minutes","WM 'Voice': exercises (about 40 sentences)."),sv("App drill",None,dr("english","Voice",8,8,"85%"))]),
 part("Part 2: Passive voice special cases",
  [rd(WM,"Voice: imperative, interrogative and modal sections"),rd(SB,"Active-passive: special rules")],
  ["Imperative: 'Open the door' → 'Let the door be opened.' Request: 'Please help me' → 'You are requested to help me.'",
   "'Who wrote this?' → 'By whom was this written?' 'What do you want?' → 'What is wanted by you?'",
   "Modals: can/may/must/should + be + V3. 'He can do it' → 'It can be done by him.'",
   "'I know him' → 'He is known to me.' 'The news pleased me' → 'I was pleased with the news.'"],
  [ex("Passive: 'Open the door.'","Let the door be opened."),ex("Passive: 'Who wrote this book?'","By whom was this book written?"),ex("Passive: 'I know him.'","He is known to me.")],
  [sv("Book practice, 45 minutes","WM 'Voice': the harder exercises on interrogative and imperative."),sv("App drill",None,dr("english","Voice",8,8,"85%"))]),
 part("Part 3: Direct and indirect speech",
  [rd(WM,"Chapter 'Narration' (Direct and Indirect Speech)"),rd(SB,"Chapter 'Narration'")],
  ["Reporting verbs: statements → said that / told; questions → asked / enquired (use if or whether for yes-no questions); commands → told / ordered / requested / advised + to + verb.",
   "Tense moves back: am/is → was; will → would; has/have → had; simple past → past perfect. A universal truth or habitual fact keeps its tense.",
   "Pronouns change to fit the reporter. Time words: now → then; today → that day; tomorrow → the next day; yesterday → the previous day; here → there; this → that.",
   "Questions become statements in order: 'He asked me what I was doing' (not 'what was I doing').",
   "Exclamations: exclaimed with joy / sorrow / surprise that."],
  [ex("Indirect: He said, 'I am busy.'","He said that he was busy."),ex("Indirect: She said, 'I will go tomorrow.'","She said that she would go the next day."),
   ex("Indirect: He said to me, 'What are you doing?'","He asked me what I was doing."),ex("Indirect: He said to her, 'Please wait.'","He requested her to wait.")],
  [sv("Book practice, 45 minutes","WM 'Narration': exercises (about 40 sentences)."),sv("App drill",None,dr("english","Narration",7,8,"85%"))])]),
unit("GA: Ancient and medieval history",[
 part("Part 1: Indus Valley, Vedic age, Buddhism, Jainism, Mauryas",
  [rd(NC8,"Quick read of the early chapters (free at ncert.nic.in)"),rd(LU,"History: Ancient India"),rd("NCERT Class 6, Our Pasts I","Chapters on Harappa, Vedic age, Mahajanapadas, Mauryas")],
  ["Indus Valley: Harappa (found by Dayaram Sahni, 1921), Mohenjo-daro (Great Bath), Lothal (dockyard), Dholavira, Kalibangan, Rakhigarhi. Bronze age, planned towns.",
   "Rigveda: 10 mandalas, 1,028 hymns. Early Vedic (pastoral) then Later Vedic (iron, kingdoms). 16 Mahajanapadas: Magadha rose first.",
   "Buddha: born at Lumbini, enlightenment at Bodh Gaya, first sermon at Sarnath, death at Kushinagar. Mahavira: 24th Tirthankara.",
   "Mauryas: Chandragupta (c. 321 BCE, with Chanakya; Megasthenes wrote Indica). Ashoka: Kalinga war c. 261 BCE, Dhamma, rock edicts in Brahmi. James Prinsep deciphered Brahmi in 1837."],
  [ex("Where is the Great Bath?","Mohenjo-daro"),ex("Who wrote Indica?","Megasthenes"),ex("Where did Buddha give his first sermon?","Sarnath"),ex("When was the Kalinga war?","About 261 BCE")],
  [sv("Make a timeline","Write 8 key events with dates from the notes. Recite twice."),sv("App drill",None,dr("ga","Ancient & Medieval History",15,10))]),
 part("Part 2: Guptas, Harsha and South India",
  [rd(LU,"History: Gupta and post-Gupta period"),rd("NCERT Class 6, Our Pasts I","Chapters on Guptas, Cholas and temples")],
  ["Gupta: Chandragupta I (319-320 CE start). Samudragupta (Allahabad Pillar inscription by Harishena, called 'Napoleon of India'). Chandragupta II Vikramaditya (Fa-Hien visited). Golden Age: Kalidasa, Aryabhata.",
   "Harsha (606-647 CE): Hiuen Tsang visited; court poet Banabhatta wrote Harshacharita. Pulakeshin II of the Chalukyas stopped Harsha on the Narmada.",
   "Pallavas: Mahabalipuram rock temples. Cholas: Rajaraja I built Brihadisvara Temple, Thanjavur (c. 1010 CE); Rajendra I founded Gangaikondacholapuram. Uttaramerur inscriptions show village self-government."],
  [ex("Who wrote Harshacharita?","Banabhatta"),ex("Which Chinese pilgrim came in Chandragupta II's time?","Fa-Hien"),ex("Who built the Brihadisvara Temple?","Rajaraja I"),ex("Who is called the 'Napoleon of India'?","Samudragupta")],
  [sv("Make a table","King / Dynasty / Famous for, 8 rows from the notes."),sv("App drill",None,dr("ga","Ancient & Medieval History",15,10))]),
 part("Part 3: Delhi Sultanate, Mughals and Vijayanagara",
  [rd(LU,"History: Medieval India"),rd("NCERT Class 7, Our Pasts II","Chapters on the Delhi Sultanate, Mughals, Vijayanagara")],
  ["Delhi Sultanate: Slave dynasty 1206 (Qutb-ud-din Aibak; Iltutmish completed Qutub Minar), Khilji (Alauddin: market reforms), Tughlaq (Muhammad bin Tughlaq: token currency, moved capital to Daulatabad), Sayyid, Lodi. Timur invaded 1398.",
   "Mughals: Babur won First Battle of Panipat 1526. Sher Shah Suri: rupee, Grand Trunk Road. Akbar (1556-1605): Mansabdari system, Todar Mal, Din-i-Ilahi, Haldighati 1576 against Maharana Pratap. Shah Jahan built the Taj Mahal. Aurangzeb ruled to 1707.",
   "Vijayanagara: founded 1336 by Harihara and Bukka; capital Hampi; Krishnadevaraya was its greatest ruler. Bahmani kingdom: 1347."],
  [ex("Who started the Qutub Minar?","Qutb-ud-din Aibak"),ex("Which Mughal started the Mansabdari system?","Akbar"),ex("Who introduced token currency?","Muhammad bin Tughlaq"),ex("Who founded Vijayanagara?","Harihara and Bukka (1336)")],
  [sv("Make a timeline","1206 to 1707, 12 events with rulers. Recite twice."),sv("App drill",None,dr("ga","Ancient & Medieval History",15,10))])])
)
add_week('p1','p1-w4',W)
